import React, { useState } from "react";

function Leaderboard() {
  const [usernamesInput, setUsernamesInput] = useState("");
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleFetch = async () => {
    const usernames = usernamesInput
      .split(",")
      .map((name) => name.trim())
      .filter((name) => name !== "");

    if (usernames.length === 0) return;

    setLoading(true);

    const results = await Promise.all(
      usernames.map(async (username) => {
        const query = {
          query: `
            query userSessionProgress($username: String!) {
              matchedUser(username: $username) {
                submitStats {
                  acSubmissionNum {
                    difficulty
                    count
                  }
                }
              }
              userContestRanking(username: $username) {
                rating
              }
            }
          `,
          variables: { username },
        };

        try {
          const res = await fetch("http://localhost:4000/api/leetcode", {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(query),
          });

          const json = await res.json();
          const user = json.data.matchedUser;
          const rating = json.data.userContestRanking?.rating || "N/A";
          const acStats = user?.submitStats?.acSubmissionNum || [];

          const getCount = (difficulty) =>
            acStats.find((x) => x.difficulty === difficulty)?.count || 0;

          const problemsSolved = getCount("All");
          const easy = getCount("Easy");
          const medium = getCount("Medium");
          const hard = getCount("Hard");

          return {
            name: username,
            problemsSolved,
            easy,
            medium,
            hard,
            contestRating: rating,
          };
        } catch (error) {
          return {
            name: username,
            problemsSolved: 0,
            easy: 0,
            medium: 0,
            hard: 0,
            contestRating: "Error",
          };
        }
      })
    );

    const sorted = results.sort((a, b) => b.problemsSolved - a.problemsSolved);
    setData(sorted);
    setLoading(false);
  };

  return (
    <div className="bg-black min-h-screen text-white px-4 py-8">
      <div className="max-w-6xl mx-auto">
        <div className="flex justify-between items-center mb-6">
          <h1 className="text-3xl font-bold">Jeet_ki_tyaari</h1>
          <div className="space-x-2">
            <button className="px-3 py-1 bg-gray-800 border border-gray-600 rounded-md text-sm">Copy Invite</button>
            <button className="px-3 py-1 bg-red-600 rounded-md text-sm">Leave Room</button>
          </div>
        </div>

        <div className="flex space-x-4 border-b border-gray-700 mb-6">
          <button className="px-4 py-2 font-semibold border-b-2 border-white">Leaderboard</button>
          <button className="px-4 py-2 text-gray-400">Notifications</button>
          <button className="px-4 py-2 text-gray-400">Comparison <span className="ml-1 text-xs bg-gray-700 px-2 py-0.5 rounded-full">Coming Soon</span></button>
        </div>

        <div className="mb-4">
          <input
            type="text"
            placeholder="Enter usernames separated by commas"
            value={usernamesInput}
            onChange={(e) => setUsernamesInput(e.target.value)}
            className="border border-gray-700 bg-gray-800 text-white p-2 rounded w-full"
          />
          <button
            onClick={handleFetch}
            className="mt-2 bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600"
          >
            Generate Leaderboard
          </button>
        </div>

        {loading && <p className="text-center text-lg">Loading...</p>}

        {data.length > 0 && (
          <table className="w-full text-left text-sm mt-6">
            <thead className="text-gray-400 border-b border-gray-600">
              <tr>
                <th className="py-2">Rank</th>
                <th>Name</th>
                <th>Total</th>
                <th className="text-green-500">Easy</th>
                <th className="text-yellow-500">Medium</th>
                <th className="text-red-500">Hard</th>
                <th>Rating</th>
              </tr>
            </thead>
            <tbody>
              {data.map((user, index) => (
                <tr
                  key={index}
                  className={`border-b border-gray-700 ${user.name === "Unknown" ? "bg-gray-800" : ""}`}
                >
                  <td className="py-3">{index + 1}</td>
                  <td className="font-medium text-blue-400">{user.name}</td>
                  <td>{user.problemsSolved}</td>
                  <td className="text-green-500">{user.easy}</td>
                  <td className="text-yellow-500">{user.medium}</td>
                  <td className="text-red-500">{user.hard}</td>
                  <td>{user.contestRating}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

export default Leaderboard;
